export function expiryWeekday(expiryTimestamp:number){return new Intl.DateTimeFormat("en-US",{weekday:"long",timeZone:"UTC"}).format(new Date(expiryTimestamp));}
export function isFridayExpiry(expiryTimestamp:number){return new Date(expiryTimestamp).getUTCDay()===5;}
export function formatExpiryWithFriday(expiryTimestamp:number|undefined,label?:string){if(expiryTimestamp===undefined)return label??"—";const date=label??new Date(expiryTimestamp).toISOString().slice(0,10);return `${date}${isFridayExpiry(expiryTimestamp)?" · FRI":""}`;}

/** Resolve the close/index used by the trigger engine from hourly open/close keyed candles. */
export function resolveUnderlyingIndex(candles:Candle[],targetTimestamp:number):ResolvedUnderlyingIndex|undefined{
 const ordered=[...candles].filter(c=>Number.isFinite(c.close)&&c.close>0).sort((a,b)=>a.openTime-b.openTime);
 const exact=ordered.find(c=>c.openTime===targetTimestamp||c.closeTime===targetTimestamp);
 if(exact)return{index:exact.close,sourceCandleTimestamp:exact.openTime===targetTimestamp?exact.openTime:exact.closeTime,lookupMethod:"exact-timestamp",distanceMs:0};
 const containing=ordered.find(c=>c.openTime<=targetTimestamp&&targetTimestamp<c.closeTime);
 if(containing)return{index:containing.close,sourceCandleTimestamp:containing.openTime,lookupMethod:"containing-candle",distanceMs:targetTimestamp-containing.openTime};
 const preceding=ordered.filter(c=>c.closeTime<=targetTimestamp).at(-1);if(!preceding)return;
 const interval=Math.max(1,preceding.closeTime-preceding.openTime);const distance=targetTimestamp-preceding.closeTime;
 return distance<=interval?{index:preceding.close,sourceCandleTimestamp:preceding.closeTime,lookupMethod:"preceding-completed-candle",distanceMs:distance}:undefined;
}

