 const result=priceInverseOption({optionType:series.optionType==="C"?"call":"put",indexPrice:targetIndex,strike:series.strike,valuationTimestamp:target,expiryTimestamp:series.expiryTimestamp,forwardPrice:forward.price,ivDecimal});
 if(result.status==="unavailable")return;
 const factor=side==="sold"?1-slippageBps/10_000:1+slippageBps/10_000;
