 if(lastExecution&&(lastExecution.sold.compatibleAmountBeforeSearchEnd>0||lastExecution.bought.compatibleAmountBeforeSearchEnd>0)){const result=unavailable(targetTimestamp,"Requested size lacks sufficient qualifying causal tape on both exact legs.",executionMode);return{...result,reasonCode:"insufficient-compatible-amount",requestedAmount:amount,shortQualifyingAmount:lastExecution.sold.compatibleAmountBeforeSearchEnd,longQualifyingAmount:lastExecution.bought.compatibleAmountBeforeSearchEnd,shortfall:Math.max(amount-lastExecution.sold.compatibleAmountBeforeSearchEnd,amount-lastExecution.bought.compatibleAmountBeforeSearchEnd,0),windowStart:order,windowEnd:lastExecution.clock.fillSearchEnd};}
