export function buildResearchExport(input:{event:BacktestEvent;spread:RetrievedSpread;entry:ResearchValuation;path?:EstimatedPathPoint[];outcomes?:EstimatedOutcome[]}){return{methodology:{version:RESEARCH_METHODOLOGY_VERSION,pricingModel:INVERSE_OPTION_MODEL,formulaConvention:"Deribit inverse-option Black–Scholes; USD theoretical value divided by target BTC index",ivUnits:{api:"percent",internal:"ivDecimal"},hierarchy:["direct amount-weighted VWAP in ±30 minutes","direct amount-weighted VWAP in ±1 hour","direct amount-weighted VWAP in ±2 hours","model-reconstructed exact-contract price using synchronized causal IV anchors from the prior 12 hours"],forwardRateAssumption:FORWARD_ASSUMPTION,missingPointPolicy:"constant-entry-IV after entry; unavailable when index or entry IV is missing"},mode:"research-estimate" as const,eventId:input.event.id,expiryWeekday:input.spread.expiryTimestamp===undefined?undefined:expiryWeekday(input.spread.expiryTimestamp),isFridayExpiry:input.spread.expiryTimestamp===undefined?false:isFridayExpiry(input.spread.expiryTimestamp),contracts:{sold:input.spread.soldContract?.instrumentName,bought:input.spread.boughtContract?.instrumentName,soldStrike:input.spread.soldContract?.strike,boughtStrike:input.spread.boughtContract?.strike,expiryTimestamp:input.spread.expiryTimestamp,expiryWeekday:input.spread.expiryTimestamp===undefined?undefined:expiryWeekday(input.spread.expiryTimestamp),isFridayExpiry:input.spread.expiryTimestamp===undefined?false:isFridayExpiry(input.spread.expiryTimestamp)},windowsUsed:input.entry.status==="priced"?[input.entry.evidenceWindowMinutes]:[],priceSource:input.entry.status==="priced"?input.entry.priceSource:"unavailable",modelEvidence:input.entry.status==="priced"?{sold:input.entry.sold.model,bought:input.entry.bought.model}:undefined,quality:input.entry.estimateQuality,slippageAssumptionBps:input.entry.status==="priced"?input.entry.slippageBps:undefined,feesBtc:input.entry.status==="priced"?input.entry.openingFeesBtc:undefined,sourceClassification:input.entry.status==="priced"?input.entry.priceSource:"unavailable",estimateDisclaimer:RESEARCH_ESTIMATE_DISCLAIMER,entryTargetIndex:input.entry.status==="priced"?input.entry.entryTargetIndex:undefined,openingCurrencyConversion:input.entry.status==="priced"?{method:OPENING_CONVERSION_METHOD,timestamp:input.entry.targetTimestamp,index:input.entry.entryTargetIndex}:undefined,openingUsdEquivalent:input.entry.status==="priced"?{soldPremium:openingUsdEquivalent(input.entry.sold.priceBtcPerContract*input.entry.amount,input.entry.entryTargetIndex),boughtPremium:openingUsdEquivalent(input.entry.bought.priceBtcPerContract*input.entry.amount,input.entry.entryTargetIndex),openingFees:openingUsdEquivalent(input.entry.openingFeesBtc,input.entry.entryTargetIndex),grossEntry:openingUsdEquivalent(input.entry.grossSpreadBtc,input.entry.entryTargetIndex),netOpening:openingUsdEquivalent(input.entry.netOpeningCashFlowBtc,input.entry.entryTargetIndex),theoreticalMaximumLossAtEntryIndex:openingUsdEquivalent(Math.max(0,(input.spread.actualWidth??input.spread.targetWidth)/input.entry.entryTargetIndex*input.entry.amount-input.entry.netOpeningCashFlowBtc),input.entry.entryTargetIndex),estimatedOpeningBalance:openingUsdEquivalent(input.entry.bought.priceBtcPerContract*input.entry.amount+input.entry.openingFeesBtc,input.entry.entryTargetIndex)}:undefined,estimatedEntry:input.entry,estimatedPath:input.path??[],estimatedOutcomes:input.outcomes??[]};}
